<script type="application/ld+json">{"@context": "https://schema.org", "@type": "FAQPage", "inLanguage": "en", "mainEntity": [{"@type": "Question", "name": "What is technical SEO?", "acceptedAnswer": {"@type": "Answer", "text": "Technical SEO is the infrastructure work that allows search engines to crawl, understand and index a website without problems. robots.txt, sitemaps, canonical tags, redirects, HTTPS, mobile-friendliness, page speed and structured data all fall within its scope."}}, {"@type": "Question", "name": "How often should a technical SEO audit be done?", "acceptedAnswer": {"@type": "Answer", "text": "For small sites that change little, a general check every few months and regular monitoring of Search Console alerts are enough. Before and right after a site migration, redesign, domain change or major software update, however, a detailed audit is a must."}}, {"@type": "Question", "name": "Why isn’t my page showing up on Google?", "acceptedAnswer": {"@type": "Answer", "text": "The most common reasons are that the page carries a noindex tag, is blocked by robots.txt, receives no links from any page, has another URL chosen as canonical due to duplicate content, or hasn’t been crawled yet. The URL Inspection tool in Search Console largely reveals the reason."}}, {"@type": "Question", "name": "What is the difference between robots.txt and noindex?", "acceptedAnswer": {"@type": "Answer", "text": "robots.txt prevents Google from crawling a page, but if the page gets links from elsewhere it can appear in the index without its content. noindex, on the other hand, allows the page to be crawled and says it should not be shown in search results. To remove a page from results, use noindex and don’t block the page with robots.txt."}}, {"@type": "Question", "name": "Is a special file like llms.txt needed for AI search?", "acceptedAnswer": {"@type": "Answer", "text": "According to Google’s official documentation, no new AI file or special markup is needed to appear in AI Overviews and AI Mode. It is enough for the page to be indexed and eligible to be shown with a snippet. How other AI services use such files varies."}}]}</script>
